import sys

# Parse registry manually using line scanning
registry_path = "/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml"

with open(registry_path, 'r') as f:
    lines = f.readlines()

# Find obs-only object norm entries
current_exp = None
current_status = None
current_sr = None
results = {0.03: [], 0.05: [], 0.1: [], 0.2: []}

norm_map = {"norm003": 0.03, "norm005": 0.05, "norm01": 0.1, "norm02": 0.2}

for line in lines:
    stripped = line.strip()
    # Detect top-level exp_id (2-space indent with colon)
    if line.startswith("  ") and not line.startswith("    ") and stripped.endswith(":"):
        # Save previous
        if current_exp and current_status == "DONE" and current_sr is not None:
            for nk, nv in norm_map.items():
                if nk in current_exp:
                    results[nv].append((current_exp, current_sr))
                    break

        current_exp = stripped.rstrip(":")
        current_status = None
        current_sr = None

    elif "status:" in stripped and current_exp:
        if "DONE" in stripped:
            current_status = "DONE"
        else:
            current_status = stripped.split("status:")[-1].strip()

    elif "success_rate:" in stripped and current_exp:
        try:
            val = stripped.split("success_rate:")[-1].strip()
            current_sr = float(val)
        except:
            pass

# Don't forget last entry
if current_exp and current_status == "DONE" and current_sr is not None:
    for nk, nv in norm_map.items():
        if nk in current_exp:
            results[nv].append((current_exp, current_sr))
            break

# Filter for obs-only + object only
for nv in sorted(results.keys()):
    filtered = [(e, s) for e, s in results[nv] if "obs-only" in e and "object" in e]
    srs = sorted([s for _, s in filtered])
    print(f"eps={nv}: n={len(filtered)}, SRs={srs}")
    for e, s in sorted(filtered):
        print(f"  {e}: {s}")
    print()
